/**
 * Theme files (`bun-os-theme/1`) resolved to tokens, browser-safe. Same contract and JSON shape as
 * `crates/bun-os-platform/src/theme.rs`: colors from the M3 dynamic scheme (material-color-
 * utilities through @aphrody/m3-tokens, parity-tested against aphrody-m3-tokens), tables from
 * `themes/m3-tables.json` (generated by `bun-os-platform-native tables` from aphrody-m3-tokens).
 */
import { type SchemeVariant, schemeFromSeed } from "@aphrody/m3-tokens/dynamic-color";
import tables from "../../themes/m3-tables.json" with { type: "json" };

export const THEME_SCHEMA = "bun-os-theme/1";

export interface TypeOverride {
  size?: number;
  lineHeight?: number;
  weight?: number;
  tracking?: number;
  font?: string;
}

export interface ThemeFile {
  $schema?: string;
  schema?: string;
  id?: string;
  name?: string;
  /** Fluent id of the display name. */
  nameKey?: string;
  color?: {
    seed?: string;
    variant?: string;
    contrast?: number;
    mode?: "dark" | "light" | "system";
    /** `art`: re-seed from the focused game's art (DIRECTION.md). */
    dynamic?: "art" | "none";
    roles?: Record<string, string>;
    light?: Record<string, string>;
    dark?: Record<string, string>;
  };
  type?: {
    font?: string;
    scale?: number;
    styles?: Record<string, TypeOverride>;
  };
  shape?: Record<string, number>;
  motion?: {
    durations?: Record<string, number>;
    easings?: Record<string, [number, number, number, number]>;
    reduced?: boolean;
  };
  elevation?: Record<string, number>;
  state?: Record<string, number>;
  space?: Record<string, number>;
  icon?: Record<string, number>;
  highContrast?: { contrast?: number; roles?: Record<string, string> };
}

export interface TypeToken {
  font: string;
  size: number;
  lineHeight: number;
  weight: number;
  tracking: number;
}

export interface Tokens {
  schema: string;
  id: string;
  seed: string;
  variant: string;
  contrast: number;
  dark: boolean;
  highContrast: boolean;
  dynamicArt: boolean;
  color: Record<string, string>;
  typescale: Record<string, TypeToken>;
  shape: Record<string, number>;
  duration: Record<string, number>;
  easing: Record<string, [number, number, number, number]>;
  elevation: Record<string, number>;
  state: Record<string, number>;
  space: Record<string, number>;
  icon: Record<string, number>;
  reducedMotion: boolean;
}

export interface ResolveOptions {
  dark?: boolean;
  highContrast?: boolean;
  /** Dynamic color seed (`#rrggbb`), e.g. from the focused art. */
  seed?: string;
  reducedMotion?: boolean;
}

const VARIANTS: Record<string, SchemeVariant> = {
  "tonal-spot": "tonalSpot",
  content: "content",
  fidelity: "fidelity",
  expressive: "expressive",
  vibrant: "vibrant",
  neutral: "neutral",
  monochrome: "monochrome",
};

/** Deep merge of theme layers (objects merge, scalars and arrays replace). */
export function mergeTheme(...layers: (ThemeFile | undefined)[]): ThemeFile {
  const merge = (a: unknown, b: unknown): unknown => {
    if (b === undefined) return a;
    if (a && b && typeof a === "object" && typeof b === "object" && !Array.isArray(a) && !Array.isArray(b)) {
      const out: Record<string, unknown> = {
        ...(a as Record<string, unknown>),
      };
      for (const [k, v] of Object.entries(b)) out[k] = merge(out[k], v);
      return out;
    }
    return b;
  };
  return layers.reduce<ThemeFile>((acc, l) => merge(acc, l) as ThemeFile, {});
}

const num = (v: string) => Number.parseFloat(v.replace(/(px|ms)$/, ""));

/** `--name: value` declarations of a CSS theme mapped onto the file schema. */
export function themeFromCss(css: string): ThemeFile {
  const file: ThemeFile = {};
  const color = (file.color ??= {});
  for (const m of css.matchAll(/--([a-z0-9-]+)\s*:\s*([^;}]+)/gi)) {
    const name = m[1] as string;
    const value = (m[2] as string).trim();
    let k: string | undefined;
    if ((k = name.match(/^bun-os-theme-(.+)$/)?.[1])) {
      if (k === "seed") color.seed = value;
      else if (k === "variant") color.variant = value;
      else if (k === "mode") color.mode = value as "dark";
      else if (k === "dynamic") color.dynamic = value as "art";
      else if (k === "contrast") color.contrast = num(value);
      else if (k === "id") file.id = value.replace(/"/g, "");
      else if (k === "name") file.name = value.replace(/"/g, "");
      else if (k === "font") (file.type ??= {}).font = value.replace(/"/g, "");
      else if (k === "type-scale") (file.type ??= {}).scale = num(value);
    } else if ((k = name.match(/^md-sys-color-(.+)$/)?.[1])) (color.roles ??= {})[k] = value;
    else if ((k = name.match(/^md-sys-shape-corner-(.+)$/)?.[1])) (file.shape ??= {})[k] = num(value);
    else if ((k = name.match(/^md-sys-motion-duration-(.+)$/)?.[1]))
      ((file.motion ??= {}).durations ??= {})[k] = num(value);
    else if ((k = name.match(/^md-sys-motion-easing-(.+)$/)?.[1])) {
      const p = value
        .replace(/^cubic-bezier\(|\)$/g, "")
        .split(",")
        .map(Number);
      if (p.length === 4) ((file.motion ??= {}).easings ??= {})[k] = p as [number, number, number, number];
    } else if ((k = name.match(/^md-sys-state-(.+)-state-layer-opacity$/)?.[1])) (file.state ??= {})[k] = num(value);
    else if ((k = name.match(/^md-sys-typescale-(.+)-(size|line-height|weight|tracking)$/)?.[1])) {
      const prop = {
        size: "size",
        "line-height": "lineHeight",
        weight: "weight",
        tracking: "tracking",
      }[name.match(/-(size|line-height|weight|tracking)$/)?.[1] as string] as keyof TypeOverride;
      (((file.type ??= {}).styles ??= {})[k] ??= {})[prop] = num(value) as never;
    } else if ((k = name.match(/^bun-os-space-(.+)$/)?.[1])) (file.space ??= {})[k] = num(value);
    else if ((k = name.match(/^bun-os-icon-(.+)$/)?.[1])) (file.icon ??= {})[k] = num(value);
  }
  return file;
}

/** Two decimals, the precision both resolvers emit (f32 on the native side). */
const round2 = (v: number) => Math.round(v * 100) / 100;

const kebabRole = (cssVar: string) => cssVar.replace(/^--md-sys-color-/, "");

export function resolveTheme(file: ThemeFile, options: ResolveOptions = {}): Tokens {
  const seed = (options.seed ?? file.color?.seed ?? "#6750a4").toLowerCase();
  const variantName = file.color?.variant && VARIANTS[file.color.variant] ? file.color.variant : "tonal-spot";
  let contrast = Math.min(1, Math.max(-1, file.color?.contrast ?? 0));
  const highContrast = options.highContrast ?? false;
  if (highContrast) contrast = Math.min(1, Math.max(-1, file.highContrast?.contrast ?? 1));
  const dark = options.dark ?? file.color?.mode !== "light";
  const roles = schemeFromSeed(seed, {
    dark,
    contrastLevel: contrast,
    variant: VARIANTS[variantName],
  });
  const color: Record<string, string> = {};
  for (const [k, v] of Object.entries(roles)) color[kebabRole(k)] = v.toLowerCase();
  Object.assign(
    color,
    file.color?.roles,
    dark ? file.color?.dark : file.color?.light,
    highContrast ? file.highContrast?.roles : {},
  );

  const scale = file.type?.scale ?? 1;
  const typescale: Record<string, TypeToken> = {};
  for (const s of tables.typography) {
    const o = file.type?.styles?.[s.name] ?? {};
    typescale[s.name] = {
      font: o.font ?? file.type?.font ?? s.font,
      size: round2((o.size ?? s.size_dp) * scale),
      lineHeight: round2((o.lineHeight ?? s.line_height_dp) * scale),
      weight: o.weight ?? s.weight,
      tracking: o.tracking ?? s.letter_spacing_dp,
    };
  }
  const shape = {
    ...Object.fromEntries(tables.shape.map(s => [s.name, s.dp])),
    ...file.shape,
  };
  const reducedMotion = (options.reducedMotion ?? false) || (file.motion?.reduced ?? false);
  const duration: Record<string, number> = {
    ...Object.fromEntries(tables.motion.durations.map(d => [d.name, d.ms])),
    ...file.motion?.durations,
  };
  if (reducedMotion) for (const k of Object.keys(duration)) duration[k] = 0;
  const easing: Record<string, [number, number, number, number]> = {
    ...Object.fromEntries(
      tables.motion.easings.map(e => [
        e.name,
        e.cubic_bezier
          .replace(/^cubic-bezier\(|\)$/g, "")
          .split(",")
          .map(Number) as [number, number, number, number],
      ]),
    ),
    ...file.motion?.easings,
  };
  const elevation = {
    ...Object.fromEntries(tables.elevation.map(e => [`level${e.level}`, e.dp])),
    ...file.elevation,
  };
  const state = { ...tables.state, ...file.state };
  return {
    schema: THEME_SCHEMA,
    id: file.id ?? "baseline",
    seed,
    variant: variantName,
    contrast,
    dark,
    highContrast,
    dynamicArt: file.color?.dynamic === "art",
    color,
    typescale,
    shape,
    duration,
    easing,
    elevation,
    state,
    space: { ...file.space },
    icon: { ...file.icon },
    reducedMotion,
  };
}

const shadows = Object.fromEntries(tables.elevation.map(e => [`level${e.level}`, e.shadow]));

/** Every non-color token as CSS custom properties (`--md-sys-*`, `--bun-os-*`). */
export function tokenDeclarations(t: Tokens, indent = "  "): string {
  const out: string[] = [
    `--bun-os-theme-id: ${t.id}`,
    `--bun-os-theme-seed: ${t.seed}`,
    `--bun-os-theme-variant: ${t.variant}`,
    `--bun-os-theme-contrast: ${t.contrast}`,
    `--bun-os-theme-dynamic: ${t.dynamicArt ? "art" : "none"}`,
  ];
  for (const [name, s] of Object.entries(t.typescale)) {
    out.push(
      `--md-sys-typescale-${name}-font: "${s.font}"`,
      `--md-sys-typescale-${name}-size: ${s.size}px`,
      `--md-sys-typescale-${name}-line-height: ${s.lineHeight}px`,
      `--md-sys-typescale-${name}-weight: ${s.weight}`,
      `--md-sys-typescale-${name}-tracking: ${s.tracking}px`,
    );
  }
  for (const [n, v] of Object.entries(t.shape)) out.push(`--md-sys-shape-corner-${n}: ${v}px`);
  for (const [n, v] of Object.entries(t.duration)) out.push(`--md-sys-motion-duration-${n}: ${v}ms`);
  for (const [n, v] of Object.entries(t.easing)) out.push(`--md-sys-motion-easing-${n}: cubic-bezier(${v.join(", ")})`);
  for (const [n, v] of Object.entries(t.elevation))
    out.push(`--md-sys-elevation-${n}: ${v}px`, `--md-sys-elevation-${n}-shadow: ${shadows[n] ?? "none"}`);
  for (const [n, v] of Object.entries(t.state)) out.push(`--md-sys-state-${n}-state-layer-opacity: ${v}`);
  for (const [n, v] of Object.entries(t.space)) out.push(`--bun-os-space-${n}: ${v}px`);
  for (const [n, v] of Object.entries(t.icon)) out.push(`--bun-os-icon-${n}: ${v}px`);
  return out.map(d => `${indent}${d};`).join("\n");
}

export function colorDeclarations(t: Tokens, indent = "  "): string {
  return Object.entries(t.color)
    .map(([role, hex]) => `${indent}--md-sys-color-${role}: ${hex};`)
    .join("\n");
}

/**
 * One stylesheet for the web from the theme file: tokens, light and dark roles (explicit
 * `data-theme` and `prefers-color-scheme`), the high-contrast scheme (`prefers-contrast: more`),
 * forced colors mapped to CSS system colors, and zero durations under reduced motion.
 */
export function themeCss(file: ThemeFile, options: { seed?: string } = {}): string {
  const light = resolveTheme(file, { dark: false, seed: options.seed });
  const dark = resolveTheme(file, { dark: true, seed: options.seed });
  const hcLight = resolveTheme(file, {
    dark: false,
    highContrast: true,
    seed: options.seed,
  });
  const hcDark = resolveTheme(file, {
    dark: true,
    highContrast: true,
    seed: options.seed,
  });
  const defaultDark = file.color?.mode !== "light";
  const base = defaultDark ? dark : light;
  const other = defaultDark ? light : dark;
  const zero = Object.keys(base.duration)
    .map(n => `    --md-sys-motion-duration-${n}: 0ms;`)
    .join("\n");
  return `/* Generated by @bun-os/platform from theme "${base.id}" (${THEME_SCHEMA}). */
:root {
  color-scheme: ${defaultDark ? "dark" : "light"};
${tokenDeclarations(base)}
${colorDeclarations(base)}
}
:root[data-theme="${defaultDark ? "light" : "dark"}"] {
  color-scheme: ${defaultDark ? "light" : "dark"};
${colorDeclarations(other)}
}
${
  file.color?.mode === "system"
    ? `@media (prefers-color-scheme: light) {
  :root:not([data-theme]) {
    color-scheme: light;
${colorDeclarations(light, "    ")}
  }
}
`
    : ""
}@media (prefers-contrast: more) {
  :root {
${colorDeclarations(defaultDark ? hcDark : hcLight, "    ")}
  }
  :root[data-theme="${defaultDark ? "light" : "dark"}"] {
${colorDeclarations(defaultDark ? hcLight : hcDark, "    ")}
  }
}
@media (forced-colors: active) {
  :root {
    --md-sys-color-primary: Highlight;
    --md-sys-color-on-primary: HighlightText;
    --md-sys-color-primary-container: Highlight;
    --md-sys-color-on-primary-container: HighlightText;
    --md-sys-color-secondary-container: ButtonFace;
    --md-sys-color-on-secondary-container: ButtonText;
    --md-sys-color-surface: Canvas;
    --md-sys-color-background: Canvas;
    --md-sys-color-surface-container-lowest: Canvas;
    --md-sys-color-surface-container-low: Canvas;
    --md-sys-color-surface-container: Canvas;
    --md-sys-color-surface-container-high: Canvas;
    --md-sys-color-surface-container-highest: Canvas;
    --md-sys-color-on-surface: CanvasText;
    --md-sys-color-on-background: CanvasText;
    --md-sys-color-on-surface-variant: CanvasText;
    --md-sys-color-outline: CanvasText;
    --md-sys-color-outline-variant: GrayText;
    --md-sys-color-error: Mark;
    --md-sys-color-scrim: Canvas;
  }
}
@media (prefers-reduced-motion: reduce) {
  :root {
${zero}
  }
}
`;
}
